import React, { useEffect, useRef, useState, useCallback } from 'react';
import { createChart } from 'lightweight-charts';
import api from '../../api';

const PERIODS = [
    { label: '1D', value: '1d', interval: '1m' },
    { label: '1W', value: '5d', interval: '5m' },
    { label: '1M', value: '1mo', interval: '15m' },
    { label: '3M', value: '3mo', interval: '1h' },
    { label: '6M', value: '6mo', interval: '1d' },
    { label: '1Y', value: '1y', interval: '1d' },
    { label: '5Y', value: '5y', interval: '1wk' },
];

const PriceChart = ({ symbol = 'RELIANCE' }) => {
    const chartContainerRef = useRef(null);
    const chartInstanceRef = useRef(null);
    const seriesInstanceRef = useRef(null);
    const lastCandleRef = useRef(null);

    const [loading, setLoading] = useState(true);
    const [selectedPeriod, setSelectedPeriod] = useState('1D');
    const [errorMsg, setErrorMsg] = useState('');
    const [livePrice, setLivePrice] = useState(null);

    const fetchData = useCallback(async (seriesInstance, pLabel) => {
        setLoading(true);
        setErrorMsg('');
        try {
            const pConfig = PERIODS.find(p => p.label === pLabel) || PERIODS[0];
            const data = await api.getHistoricalData(symbol, pConfig.value, pConfig.interval);

            if (data && data.length > 0) {
                // Ensure strictly ascending times without duplicate timestamps
                const cleanData = [];
                let lastTime = 0;
                for (const item of data) {
                    if (item.time > lastTime) {
                        cleanData.push(item);
                        lastTime = item.time;
                    }
                }

                seriesInstance.setData(cleanData);
                if (cleanData.length > 0) {
                    lastCandleRef.current = { ...cleanData[cleanData.length - 1] };
                    setLivePrice(lastCandleRef.current.close);
                }

                if (chartInstanceRef.current) {
                    chartInstanceRef.current.timeScale().fitContent();
                }
            } else {
                setErrorMsg('No trading chart data available for this timeframe.');
            }
        } catch (error) {
            console.error('Error fetching chart data:', error);
            setErrorMsg('Unable to load chart. Please check backend connection.');
        }
        setLoading(false);
    }, [symbol]);

    useEffect(() => {
        if (!chartContainerRef.current) return;

        if (chartInstanceRef.current) {
            chartInstanceRef.current.remove();
            chartInstanceRef.current = null;
        }

        // Initialize TradingView Lightweight Charts with Soft Dark Theme & Full Candlesticks
        const newChart = createChart(chartContainerRef.current, {
            width: chartContainerRef.current.clientWidth,
            height: 420,
            layout: {
                background: { color: '#182234' },
                textColor: '#94a3b8',
                fontSize: 12,
            },
            grid: {
                vertLines: { color: '#243247' },
                horzLines: { color: '#243247' },
            },
            crosshair: {
                mode: 0,
            },
            timeScale: {
                borderColor: '#26354d',
                timeVisible: true,
                secondsVisible: false,
            },
            rightPriceScale: {
                borderColor: '#26354d',
                autoScale: true
            },
        });

        // Add Full Standard Candlestick Series (Body, Wicks, Borders)
        const newSeries = newChart.addCandlestickSeries({
            upColor: '#10b981',           // Solid Emerald Green for Bullish Candles
            downColor: '#f43f5e',         // Solid Coral Rose for Bearish Candles
            borderVisible: true,
            borderUpColor: '#10b981',
            borderDownColor: '#f43f5e',
            wickUpColor: '#10b981',
            wickDownColor: '#f43f5e',
        });

        chartInstanceRef.current = newChart;
        seriesInstanceRef.current = newSeries;

        fetchData(newSeries, selectedPeriod);

        const handleResize = () => {
            if (chartContainerRef.current && chartInstanceRef.current) {
                chartInstanceRef.current.resize(
                    chartContainerRef.current.clientWidth,
                    420
                );
            }
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            if (chartInstanceRef.current) {
                chartInstanceRef.current.remove();
                chartInstanceRef.current = null;
            }
        };
    }, [symbol, fetchData, selectedPeriod]);

    // Live Tick Chart Auto-Update Every 5 Seconds
    useEffect(() => {
        const liveInterval = setInterval(async () => {
            if (!symbol || !seriesInstanceRef.current || !lastCandleRef.current) return;
            try {
                const quote = await api.getPrice(symbol);
                if (quote && quote.price) {
                    const price = quote.price;
                    setLivePrice(price);

                    const last = lastCandleRef.current;
                    const updatedCandle = {
                        time: last.time,
                        open: last.open,
                        high: Math.max(last.high, price),
                        low: Math.min(last.low, price),
                        close: price
                    };
                    lastCandleRef.current = updatedCandle;
                    seriesInstanceRef.current.update(updatedCandle);
                }
            } catch (e) {}
        }, 5000);

        return () => clearInterval(liveInterval);
    }, [symbol]);

    return (
        <div className="soft-card" style={{ padding: '20px', position: 'relative' }}>
            <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                marginBottom: '16px',
                flexWrap: 'wrap',
                gap: '12px'
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <h3 style={{ color: 'var(--text-primary)', margin: 0, fontSize: '18px', fontWeight: '800' }}>
                        📊 {symbol} Real-Time Candlestick Chart
                    </h3>
                    {livePrice && (
                        <span style={{ 
                            fontSize: '15px', 
                            fontWeight: '800', 
                            color: 'var(--accent-emerald)',
                            background: 'var(--accent-emerald-soft)',
                            padding: '4px 10px',
                            borderRadius: '8px'
                        }}>
                            ₹{livePrice.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </span>
                    )}
                    {loading && (
                        <span style={{ color: 'var(--accent-primary)', fontSize: '13px', fontWeight: '600' }}>
                            Loading candles...
                        </span>
                    )}
                </div>
                <div style={{ display: 'flex', gap: '6px', background: '#111927', padding: '4px', borderRadius: '10px' }}>
                    {PERIODS.map((p) => {
                        const isSelected = selectedPeriod === p.label;
                        return (
                            <button
                                key={p.label}
                                onClick={() => setSelectedPeriod(p.label)}
                                style={{
                                    padding: '5px 12px',
                                    background: isSelected ? 'var(--accent-primary)' : 'transparent',
                                    color: isSelected ? '#ffffff' : 'var(--text-secondary)',
                                    border: 'none',
                                    borderRadius: '6px',
                                    cursor: 'pointer',
                                    fontSize: '12px',
                                    fontWeight: isSelected ? '700' : '500',
                                    transition: 'all 0.2s'
                                }}
                            >
                                {p.label}
                            </button>
                        );
                    })}
                </div>
            </div>

            {errorMsg && (
                <div style={{
                    padding: '12px',
                    background: 'var(--accent-rose-soft)',
                    color: 'var(--accent-rose)',
                    borderRadius: '8px',
                    fontSize: '13px',
                    marginBottom: '12px'
                }}>
                    {errorMsg}
                </div>
            )}

            <div ref={chartContainerRef} style={{ width: '100%', height: '420px', borderRadius: '8px', overflow: 'hidden' }} />
        </div>
    );
};

export default PriceChart;
